def choose_move(observation):
    def _pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def _sign(n):
        return 1 if n > 0 else (-1 if n < 0 else 0)

    def _move_toward(a, b):
        ax, ay = a
        bx, by = b
        return [_sign(bx - ax), _sign(by - ay)]

    def _dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def _clip_move(m):
        dx = m[0] if m[0] in (-1, 0, 1) else 0
        dy = m[1] if m[1] in (-1, 0, 1) else 0
        return [dx, dy]

    sx, sy = _pos(observation.get("self_position"), (0, 0))
    ox, oy = _pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    env = observation.get("environment_name", "resource_collection")
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    role = observation.get("self_role", "collector")

    resources = observation.get("resources") or []
    unclaimed = observation.get("unclaimed_cells") or []
    opp_terr = observation.get("opponent_territory") or []
    own_terr = observation.get("self_territory") or []

    def _inside(p):
        if w and h:
            return 0 <= p[0] < w and 0 <= p[1] < h
        return True

    def _score_move(m):
        nx, ny = sx + m[0], sy + m[1]
        p = (nx, ny)
        score = 0

        if w and h:
            score -= 2 * (nx < 0 or ny < 0 or nx >= w or ny >= h)

        if env == "pursuit_evasion":
            if role == "pursuer":
                score += 6 - _dist(p, opp_pos)
                if p == opp_pos:
                    score += 8
            else:
                score += _dist(p, opp_pos)
                if w and h:
                    corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
                    score += max(_dist(p, c) for c in corners) * 0.2
        elif env == "territory_control":
            targets = unclaimed or opp_terr
            if targets:
                best = min((_pos(t, p) for t in targets), key=lambda q: _dist(p, q))
                score += 5 - _dist(p, best)
            if own_terr:
                best_own = min((_pos(t, p) for t in own_terr), key=lambda q: _dist(p, q))
                score += 0.2 * (3 - _dist(p, best_own))
        else:
            if resources:
                best_res = min((_pos(t, p) for t in resources), key=lambda q: _dist(p, q))
                score += 6 - _dist(p, best_res)
            else:
                score += 1 - _dist(p, opp_pos) * 0.1

        score += 0.05 * (abs(m[0]) + abs(m[1]))
        if m == [0, 0]:
            score -= 0.1
        return score

    candidates = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            candidates.append([dx, dy])

    best_move = [0, 0]
    best_score = None
    for m in candidates:
        m = _clip_move(m)
        s = _score_move(m)
        if best_score is None or s > best_score:
            best_score = s
            best_move = m

    return best_move

